"""guide/glossary.json: terms new to the survey-v3 guide. Each entry names its chapter and the section heading (by its
number) where it is built; the anchor slug is computed from the actual heading so it cannot drift."""
import json, os, re
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
slug = lambda h: "n-" + re.sub(r"[^a-z0-9]+", "-", h.lower()).strip("-")
def anchor(ch, num):
    t = open(os.path.join(ROOT, "guide", ch, "text.md"), encoding="utf-8").read()
    h = next(x for x in re.findall(r"^## (.+)$", t, re.M) if x.startswith(f"{num}."))
    return slug(h)
T = {
 "multiplier": ("conditioning", 4, "multiplier $1 - \\eta\\lambda$", "Near a stationary point, one gradient-descent step multiplies the error along a Hessian eigenvector with eigenvalue $\\lambda$ by $1 - \\eta\\lambda$. It contracts for $0 < \\eta\\lambda < 2$, grows without changing sign for $\\lambda < 0$, and grows while flipping sign for $\\eta\\lambda > 2$.", "e_{t+1} \\approx (I - \\eta H^\\star)e_t"),
 "variable-metric": ("metric", 1, "variable-metric step", "The step that minimizes the linear model plus a penalty measured in a positive-definite metric $M$: $\\Delta = -\\eta M^{-1}g$. $M = I$ gives GD, a diagonal $M$ per-coordinate scaling, $M = H$ Newton, $M = F$ natural gradient. A lens, not an identity: Adam's moments are not a Hessian, and Muon's geometry is not a quadratic metric.", "\\Delta_t = \\arg\\min_\\Delta\\, g_t^\\top\\Delta + \\tfrac{1}{2\\eta}\\Delta^\\top M_t\\Delta = -\\eta M_t^{-1}g_t"),
 "optimizer-state": ("compare", 2, "optimizer state", "What an optimizer keeps between steps besides the weights and gradients: nothing for SGD, one vector for momentum and Lion, two for Adam, row and column sums for Adafactor, two factor matrices per layer for K-FAC and Shampoo.", None),
 "adafactor-factored": ("lean", 1, "factored second moment (Adafactor)", "Adafactor stores only the row sums $r$ and column sums $c$ of an $m\\times n$ second-moment matrix and rebuilds it as $r_ic_j/\\sum_k r_k$: $m + n$ numbers instead of $mn$. Exact when the matrix is a product of a row and a column factor.", "\\widetilde V_{ij} = \\frac{r_ic_j}{\\sum_k r_k}"),
 "lion": ("lean", 2, "Lion", "A sign-based optimizer found by program search: it steps by $-\\eta\\,\\mathrm{sign}(\\beta_1m + (1-\\beta_1)g)$, so every coordinate moves by exactly $\\eta$; the momentum $m$ uses a second coefficient $\\beta_2$. One state array instead of Adam's two.", "\\theta \\leftarrow (1-\\eta\\lambda)\\theta - \\eta\\,\\mathrm{sign}(c_t)"),
 "decoupled-decay": ("adaptive", 5, "decoupled weight decay (AdamW)", "Shrinking every weight by the same factor $1 - \\eta\\lambda$, separately from the adaptive step. Adding an L2 penalty inside Adam instead divides the decay by each coordinate's adaptive scale, so heavily updated weights are barely regularized.", "\\theta_{t+1} = (1-\\eta\\lambda)\\theta_t - \\eta\\frac{\\hat m_t}{\\sqrt{\\hat v_t}+\\varepsilon}"),
 "damping": ("newton", 3, "damping", "Replacing the Hessian by $H + \\lambda I$ in Newton's equation. If $H + \\lambda I \\succ 0$ the step is a descent direction, even where $H$ is indefinite; large $\\lambda$ makes the step short, like gradient descent.", "(H_t + \\lambda_tI)\\Delta_t = -g_t"),
 "trust-region": ("newton", 4, "trust region", "A method that minimizes the quadratic model only within a radius $r_t$, then grows or shrinks the radius by comparing the actual decrease of the loss with the predicted one. It handles negative curvature naturally.", "\\min_{\\|\\Delta\\|\\le r_t}\\, g_t^\\top\\Delta + \\tfrac12\\Delta^\\top H_t\\Delta"),
 "secant": ("quasinewton", 1, "secant condition", "The requirement that a curvature estimate reproduce the observed change of the gradient: $B_{t+1}s_t = y_t$, with $s_t$ the last step and $y_t$ the change in gradient. Quasi-Newton methods learn curvature from these pairs without second derivatives.", "B_{t+1}s_t = y_t"),
 "bfgs": ("quasinewton", 1, "BFGS", "The classical quasi-Newton update (Broyden, Fletcher, Goldfarb, Shanno): a rank-two correction that satisfies the secant condition and keeps the estimate positive definite when $y_t^\\top s_t > 0$. L-BFGS keeps only the last $k$ pairs.", "B_{t+1} = B_t - \\frac{B_ts_ts_t^\\top B_t}{s_t^\\top B_ts_t} + \\frac{y_ty_t^\\top}{y_t^\\top s_t}"),
 "conjugate-gradient": ("quasinewton", 4, "conjugate gradients (CG)", "An iterative solver for $A\\Delta = -g$ with positive-definite $A$ that needs only products $Av$. Its rate depends on $\\sqrt\\kappa$ instead of $\\kappa$, and in exact arithmetic it finishes in at most $d$ iterations. The inner solver of Hessian-free optimization.", None),
 "ggn": ("fisher", 1, "generalized Gauss–Newton matrix", "The first term of the Hessian of a composite loss, $G = J^\\top H_\\ell J$, where $J$ is the Jacobian of the network outputs and $H_\\ell$ the Hessian of the loss in those outputs. Positive semidefinite when $H_\\ell$ is, even if the full Hessian is not.", "G = J^\\top H_\\ell J"),
 "fisher": ("fisher", 1, "Fisher information matrix", "The expected outer product of the score $\\nabla_\\theta\\log p_\\theta(y\\mid x)$, with labels drawn from the model itself. It measures how much a parameter step changes the model's predictions: $\\mathrm{KL}(p_\\theta\\|p_{\\theta+\\Delta}) \\approx \\tfrac12\\Delta^\\top F\\Delta$.", "F = \\mathbb{E}_{y\\sim p_\\theta}[\\nabla\\log p_\\theta\\,\\nabla\\log p_\\theta^\\top]"),
 "empirical-fisher": ("fisher", 1, "empirical Fisher", "The Fisher formula evaluated with the observed labels instead of labels drawn from the model: a gradient outer-product estimate. It does not generally equal the Fisher, the Gauss–Newton matrix, or the Hessian.", None),
 "natural-gradient": ("fisher", 2, "natural gradient", "The step $-\\eta F^{-1}g$: the steepest descent direction when step size is measured by how much the predictions change (KL divergence), not by Euclidean distance in parameters. Approximately invariant to how the model is parameterized.", "\\Delta_{\\mathrm{NG}} = -\\eta F^{-1}g"),
 "kronecker": ("kfac", 1, "Kronecker product", "$A\\otimes S$ is the block matrix whose $(j, l)$ block is $A_{jl}S$. Its inverse is $A^{-1}\\otimes S^{-1}$, so a huge $mn\\times mn$ matrix that is a Kronecker product can be stored and inverted through an $n\\times n$ and an $m\\times m$ factor.", "(A\\otimes S)^{-1} = A^{-1}\\otimes S^{-1}"),
 "kfac": ("kfac", 3, "K-FAC", "Kronecker-factored approximate curvature: it approximates a layer's Fisher block $\\mathbb{E}[(aa^\\top)\\otimes(\\delta\\delta^\\top)]$ by $\\mathbb{E}[aa^\\top]\\otimes\\mathbb{E}[\\delta\\delta^\\top]$, exact when activations and back-propagated errors are independent.", "F_W \\approx A\\otimes S"),
 "hutchinson": ("diagonal", 2, "Hutchinson's estimator", "For a random vector $z$ of independent $\\pm1$ entries, $z\\odot(Hz)$ is an unbiased estimate of the diagonal of $H$, at the cost of one Hessian-vector product. Averaging $k$ probes reduces the error like $1/\\sqrt k$.", "\\hat h = z\\odot(Hz),\\quad \\mathbb{E}[\\hat h] = \\operatorname{diag}(H)"),
 "sophia": ("diagonal", 3, "Sophia", "A language-model optimizer that divides momentum by an occasional diagonal Hessian estimate and clips each coordinate's step to $\\pm\\rho$, so tiny or negative curvature estimates cannot produce huge steps.", "\\Delta\\theta_t = -\\eta_t\\,\\mathrm{clip}\\left(\\frac{m_t}{\\max\\{h_t,\\epsilon\\}}, -\\rho, \\rho\\right)"),
 "soap": ("muon", 1, "SOAP", "Adam run in the rotated basis given by Shampoo's eigenvectors: the gradient is rotated to $U^\\top GV$, Adam-style moments are kept there, and the step is rotated back.", "\\widetilde G = U^\\top GV"),
 "polar-factor": ("muon", 2, "polar factor (msign)", "For $M = U\\Sigma V^\\top$, the matrix $UV^\\top$: the same singular directions with every nonzero singular value set to one. Muon's update direction.", "\\mathrm{msign}(M) = UV^\\top"),
 "spectral-norm": ("muon", 3, "spectral norm", "The largest singular value of a matrix, $\\|\\Delta\\|_2$: how much $\\Delta$ can stretch any vector. Under the budget $\\|\\Delta\\|_2\\le\\eta$, the steepest linearized step is $-\\eta UV^\\top$.", "\\min_{\\|\\Delta\\|_2\\le\\eta}\\langle G,\\Delta\\rangle_F = -\\eta\\sum_i\\sigma_i(G)"),
 "newton-schulz": ("muon", 4, "Newton–Schulz iteration", "A matrix-multiplication iteration that pushes every singular value toward one, approximating the polar factor without an SVD: $X \\leftarrow \\tfrac12X(3I - X^\\top X)$. It has nothing to do with the loss's Hessian.", "s \\leftarrow \\tfrac12 s(3 - s^2)"),
}
out = {}
for k, (ch, num, term, d, tex) in T.items():
    e = {"term": term, "ch": ch, "def": d, "sec": anchor(ch, num)}
    if tex: e["tex"] = tex
    out[k] = e
json.dump(out, open(os.path.join(ROOT, "guide", "glossary.json"), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
print(len(out), "terms")
